void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double freq_matrix[4][4];
    double transform_matrix[4][4];
    double vector[4];
    int i, j, k;

    // Compute kernel
    for (i = 0; i < 4; i++) {
        kernel[i] = (mul * (i + 1)) / (r2 * r2);
    }

    // Apply filtering and blurring operations on frequency matrices
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            freq_matrix[i][j] = (double) index[i] / (index[j] + 1);
        }
    }

    // Calculate transformation matrix
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            transform_matrix[i][j] = freq_matrix[i][j] * kernel[j];
        }
    }

    // Compute vector based on frequency matrices
    for (i = 0; i < 4; i++) {
        vector[i] = freq_matrix[i][0] + freq_matrix[i][1] + freq_matrix[i][2] + freq_matrix[i][3];
    }

    // Update mu array with matrix-vector multiplication
    for (i = 0; i < 4; i++) {
        mu[i] = 0.0;
        for (j = 0; j < 4; j++) {
            mu[i] += transform_matrix[i][j] * vector[j];
        }
    }

    // Ensure all values are non-negative
    for (i = 0; i < 4; i++) {
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double transformation[4][4];
    double vector[4];
    int i, j;

    // Compute kernel based on the multiplier and r2
    for (i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-index[i] * index[i] / (2 * r2 * r2));
    }

    // Apply prefilter iterations to kernel
    for (i = 0; i < prefilter; i++) {
        double kernel_copy[4];
        for (j = 0; j < 4; j++) {
            kernel_copy[j] = kernel[j];
        }

        for (j = 0; j < 4; j++) {
            kernel[j] = 0.25 * (kernel_copy[(j + 1) % 4] + kernel_copy[j] + kernel_copy[(j + 3) % 4]);
        }
    }

    // Calculate transformation matrix
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            transformation[i][j] = kernel[(i + j) % 4];
        }
    }

    // Compute vector based on frequency matrices and indices
    for (i = 0; i < 4; i++) {
        vector[i] = index[i] * (index[i] + 1);
    }

    // Matrix-vector multiplication
    for (i = 0; i < 4; i++) {
        mu[i] = 0;
        for (j = 0; j < 4; j++) {
            mu[i] += transformation[i][j] * vector[j];
        }
    }

    // Ensure all values are non-negative
    for (i = 0; i < 4; i++) {
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double freq[4] = {0.0};
    double transformed[4] = {0.0};
    double vector[4] = {0.0};

    // Compute kernel based on multiplier
    for (int i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-index[i] * index[i] / (2.0 * r2));
    }

    // Apply prefiltering
    for (int iter = 0; iter < prefilter; iter++) {
        double sum = 0.0;
        for (int i = 0; i < 4; i++) {
            freq[i] = kernel[i] * freq[i] + 0.25 * (kernel[i] + kernel[(i + 1) % 4]);
            sum += freq[i];
        }
        for (int i = 0; i < 4; i++) {
            freq[i] /= sum;
        }
    }

    // Calculate transformation matrix (identity matrix for simplicity)
    for (int i = 0; i < 4; i++) {
        transformed[i] = freq[i];
    }

    // Compute vector based on frequency matrices
    for (int i = 0; i < 4; i++) {
        vector[i] = freq[i] * transformed[i];
    }

    // Compute matrix-vector multiplication
    for (int i = 0; i < 4; i++) {
        mu[i] = 0.0;
        for (int j = 0; j < 4; j++) {
            mu[i] += transformed[i] * vector[j];
        }
        mu[i] = (mu[i] < 0.0) ? 0.0 : mu[i];
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double frequency_matrix[4][4];
    double transformation_matrix[4][4];
    double vector[4];
    int i, j;

    // Initialize kernel based on multiplier and r2
    for (i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-r2 * (i - index[0]) * (i - index[0]));
    }

    // Apply filtering and blurring on frequency matrix
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            frequency_matrix[i][j] = kernel[i] * kernel[j];
        }
    }

    // Compute transformation matrix
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            transformation_matrix[i][j] = frequency_matrix[i][j] * (1 + prefilter);
        }
    }

    // Compute vector based on frequency matrix and indices
    for (i = 0; i < 4; i++) {
        vector[i] = frequency_matrix[index[i]][index[i]] * r2;
    }

    // Perform matrix-vector multiplication
    for (i = 0; i < 4; i++) {
        mu[i] = 0.0;
        for (j = 0; j < 4; j++) {
            mu[i] += transformation_matrix[i][j] * vector[j];
        }

        // Ensure non-negative values
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}

void calculate_coefficients(double mu[4], const int index[4], int prefilter, double r2, double mul) {
    double kernel[4];
    double freq_matrix[4][4];
    double transform_matrix[4][4];
    double vector[4] = {0.0, 0.0, 0.0, 0.0};
    int i, j;

    // Compute kernel based on the input multiplier
    for (i = 0; i < 4; i++) {
        kernel[i] = mul * exp(-index[i] * index[i] / (2 * r2));
    }

    // Apply filtering and blurring operations on frequency matrices
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            freq_matrix[i][j] = kernel[i] * kernel[j];
        }
    }

    // Calculate the transformation matrix
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            transform_matrix[i][j] = freq_matrix[i][j] * (i + j + 1);
        }
    }

    // Compute vector based on frequency matrices
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++) {
            vector[i] += freq_matrix[i][j] * index[j];
        }
    }

    // Update the mu array with results of matrix-vector multiplication
    for (i = 0; i < 4; i++) {
        double result = 0.0;
        for (j = 0; j < 4; j++) {
            result += transform_matrix[i][j] * vector[j];
        }
        mu[i] = result;
    }

    // Ensure all values in mu are non-negative
    for (i = 0; i < 4; i++) {
        if (mu[i] < 0.0) {
            mu[i] = 0.0;
        }
    }
}
